        const props = this.props;
        const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
        return <Shell ready={this.#ready} fallback={this.fallback} preview={this.preview}><main><Card children={(slots.header = <h2>Assigned header {rows.flatMap(row => [<b key={row.id}>Top {row.name}</b>, <Fragment key={row.id + "-tail"}>Tail {row.value}</Fragment>])}</h2>, rows.flatMap(row => [<b key={row.id}>Top {row.name}</b>, <Fragment key={row.id + "-tail"}>Tail {row.value}</Fragment>]))}
