          : <aside key={row.id}>Closed {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</aside>)}</section>
      : <footer>Disabled {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</footer>} root tail {count}</main></Shell>;
      }
    }

