export const Page = async (props: PageProps) => {
      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      await preload();
      return <><p>Async arrow preview {count}</p><table><caption>Grouped results {count}</caption><tbody>
      {rows.map((row, index) => <Fragment key={row.id}><tr>
        <th>{row.name}</th><td>Cell {enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>}</td>
        <td><Card render={({ active }) => active ? <b>Active {enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>}</b> : <Value>{row.raw}</Value>} /></td>
      </tr>{row.children?.map(child => <tr key={child.id}><td colSpan={index + 1}>Nested {child.name}</td></tr>)}</Fragment>)}
    </tbody></table></>;
    };

